USE nyc311;
CREATE TABLE IF NOT EXISTS ads_daily_status (release_id BIGINT UNSIGNED NOT NULL,created_day DATE NOT NULL,status VARCHAR(40) NOT NULL,ticket_count BIGINT UNSIGNED NOT NULL,PRIMARY KEY(release_id,created_day,status),CONSTRAINT fk_ads_daily_release FOREIGN KEY(release_id) REFERENCES release_registry(release_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ads_agency_status (release_id BIGINT UNSIGNED NOT NULL,agency VARCHAR(32) NOT NULL,borough VARCHAR(40) NOT NULL,status VARCHAR(40) NOT NULL,ticket_count BIGINT UNSIGNED NOT NULL,PRIMARY KEY(release_id,agency,borough,status),CONSTRAINT fk_ads_agency_release FOREIGN KEY(release_id) REFERENCES release_registry(release_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ads_complaint (release_id BIGINT UNSIGNED NOT NULL,complaint_type VARCHAR(255) NOT NULL,ticket_count BIGINT UNSIGNED NOT NULL,PRIMARY KEY(release_id,complaint_type),CONSTRAINT fk_ads_complaint_release FOREIGN KEY(release_id) REFERENCES release_registry(release_id)) ENGINE=InnoDB;
